substitutions.old:
$stdout = Join-Path $evidence "$Trial-alpine-import.stdout.log"
$stderr = Join-Path $evidence "$Trial-alpine-import.stderr.log"
$process = Start-Process -FilePath $wsl -ArgumentList @('--import',$name,$install,$rootfs,'--version','2') -RedirectStandardOutput $stdout -RedirectStandardError $stderr -PassThru
if (-not $process.WaitForExit(45000)) {
    $killer = Start-Process -FilePath 'C:\Windows\System32\taskkill.exe' -ArgumentList @('/PID',[string]$process.Id,'/T','/F') -Wait -PassThru -WindowStyle Hidden
    $null = $process.WaitForExit(10000)
    throw "Alpine import timed out; taskkill exit $($killer.ExitCode), process stopped $($process.HasExited)."
}
if ($process.ExitCode -ne 0) { throw "Alpine import failed with exit $($process.ExitCode)." }

$stdout = Join-Path $evidence "$Trial-alpine-unregister.stdout.log"
$stderr = Join-Path $evidence "$Trial-alpine-unregister.stderr.log"
